INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3370, 'ក្នុងត្រីកោណ \(ABC\) មាន \(\angle B = 70^\circ\) និង \(\angle C = 47^\circ\)។ គណនា \(\angle A\) និងមុំក្រៅត្រង់ \(A\)។', NULL, '[]', 0, NULL, 5, 'writing', '\(\angle A = 180^\circ - 70^\circ - 47^\circ = 63^\circ\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3371, 'ផលបូករង្វាស់មុំក្នុងពីរនៃត្រីកោណមួយស្មើ \(130^\circ\) ហើយផលដករបស់វាស្មើ \(20^\circ\)។ គណនាមុំក្នុងទាំងបីនៃត្រីកោណ។', NULL, '[]', 0, NULL, 5, 'writing', 'តាងមុំពីរ \(x, y\) \((x > y)\) ៖ \(x + y = 130\) \(x - y = 20\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3372, 'ក្នុងត្រីកោណ \(ABC\) បង្ហាញថាមុំក្រៅត្រង់ \(A\) (\(\angle BAz\) ដែល \(Az\) ជាបន្លាយនៃ \(CA\)) ស្មើនឹងផលបូកមុំក្នុង \(B\) និង \(C\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ផលបូកមុំក្នុង \(\angle A + \angle B + \angle C = 180^\circ\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3373, 'ដំបូលរោងមួយរាងត្រីកោណសមបាត មុំកំពូលស្មើ \(\dfrac{2}{3}\) នៃមុំកែង។ ក. រកមុំកំពូល និងមុំបាត។ ខ. ជាត្រីកោណប្រភេទអ្វី? គ. បើជ្រុងមួយ \(6\ \text{m}\) បរិមាត្រដំបូលប៉ុន្មាន?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. មុំកំពូល \(60^\circ\) មុំបាត \(60^\circ\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3374, 'ដីចម្ការរាងចតុកោណកែង បណ្តោយ \(24\ \text{m}\) ទទឹង \(10\ \text{m}\)។ ក. បរិមាត្រ? ខ. ថ្លៃរបងមួយជុំ បើមួយម៉ែត្រ \(3\,000\) ៛? គ. បើដាក់របង \(3\) ជុំ ថ្លៃប៉ុន្មាន?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(P = 2(24 + 10) = 68\ \text{m}\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3375, 'ផ្លាកសញ្ញាចរាចរណ៍រាងត្រីកោណសម័ង្សជ្រុង \(60\ \text{cm}\)។ ក. បិទកាសែតភ្លឺជុំវិញគែមមួយជុំប្រើប៉ុន្មាន cm? ខ. ក្នុង \(25\) ផ្លាក ប្រើកាសែតប៉ុន្មានម៉ែត្រ? គ. មុំនីមួយៗនៃផ្លាកមានប៉ុន្មានដឺក្រេ?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(3 \times 60 = 180\ \text{cm}\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3376, 'ក្រុមហ៊ុនធ្វើស៊ុមរូបរាងចតុកោណកែង បណ្តោយ \(40\ \text{cm}\) ទទឹង \(30\ \text{cm}\)។ ក. ប្រវែងឈើត្រូវការសម្រាប់ស៊ុមមួយ។ ខ. ស៊ុម \(12\) ប្រវែងឈើសរុបប៉ុន្មានម៉ែត្រ? គ. ឈើមួយម៉ែត្រថ្លៃ \(8\,000\) ៛ ថ្លៃឈើសរុបប៉ុន្មាន?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(P = 2(40 + 30) = 140\ \text{cm}\) (2 ពិន្ទុ)
